#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* convert(const char* s, int numRows) {
    if (!s) return strdup("");
    int n = strlen(s);
    if (numRows <= 1 || numRows >= n) return strdup(s);
    int rowsCount = numRows < n ? numRows : n;
    char **rows = malloc(sizeof(char*) * rowsCount);
    int *sizes = calloc(rowsCount, sizeof(int));
    int *caps = malloc(sizeof(int) * rowsCount);
    for (int i = 0; i < rowsCount; ++i) { caps[i] = 16; rows[i] = malloc(caps[i]); rows[i][0] = '\0'; }
    int cur = 0, dir = 1;
    for (int i = 0; i < n; ++i) {
        if (sizes[cur] + 2 > caps[cur]) { caps[cur] *= 2; rows[cur] = realloc(rows[cur], caps[cur]); }
        rows[cur][sizes[cur]++] = s[i]; rows[cur][sizes[cur]] = '\0';
        if (cur == 0) dir = 1; else if (cur == rowsCount - 1) dir = -1; cur += dir;
    }
    int total = 0; for (int i = 0; i < rowsCount; ++i) total += sizes[i];
    char *out = malloc(total + 1); int oi = 0;
    for (int i = 0; i < rowsCount; ++i) { memcpy(out + oi, rows[i], sizes[i]); oi += sizes[i]; free(rows[i]); }
    out[oi] = '\0'; free(rows); free(sizes); free(caps); return out;
}

