class Solution {
public:
    string convert(string s, int numRows) {
        if (numRows <= 1 || numRows >= (int)s.length()) return s;
        vector<string> rows(min(numRows, (int)s.length()));
        int cur = 0, dir = 1;
        for (char c : s) {
            rows[cur] += c;
            if (cur == 0) dir = 1;
            else if (cur == numRows - 1) dir = -1;
            cur += dir;
        }
        string out = "";
        for (const string& row : rows) out += row;
        return out;
    }
};

