        if numRows <= 1 or numRows >= len(s):
            return s
        rows = ["" for _ in range(min(numRows, len(s)))]
        cur, dir = 0, 1
        for c in s:
            rows[cur] += c
            if cur == 0:
                dir = 1
            elif cur == numRows - 1:
                dir = -1
            cur += dir
